<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Reports" show-doc />
    <ReportListFilters :params="params" />
    <Card>
      <CardContent class="!p-0">
        <AppLoader v-if="isLoading" variant="inline" subject="reports" />
        <AppError
          v-else-if="error"
          title="Failed to load reports"
          :error="error"
          variant="table"
          :action="refetch"
          action-text="Retry"
        />
        <template v-else>
          <ResponsiveTable rounded>
            <ResponsiveTableHeader>
              <ResponsiveTableHead class="text-accent-foreground text-xs sm:text-sm leading-6"
                >Canvasser
              </ResponsiveTableHead>
              <ResponsiveTableHead>Project</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit">Created At</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit">State</ResponsiveTableHead>
              <ResponsiveTableHead class="text-center w-fit">Review Status</ResponsiveTableHead>
            </ResponsiveTableHeader>
            <ResponsiveTableBody>
              <ResponsiveTableEmpty
                v-if="(totalCount === 0 || items.length === 0) && !isLoading"
                :colspan="5"
                :cols="4"
                :cols-sm="4"
                cell-class="text-center"
              >
                <AppGuidedEmpty v-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
                <AppEmpty v-else subject="reports" variant="table" />
              </ResponsiveTableEmpty>
              <ResponsiveTableRow
                v-for="item in items"
                v-else
                :key="item.id"
                :to="{ name: 'reports-id', params: { id: item.id } }"
              >
                <ResponsiveTableCell :cols="4" :cols-sm="3" label="Canvasser">
                  <UserNameWithCompany :user="item.canvasser" />
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="4" :cols-sm="3" label="Project">
                  <p class="text-base">
                    {{ item.project.name }}
                  </p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="4" :cols-sm="1" label="Created At">
                  <p class="text-base md:text-center">
                    {{ formatDateTzToFormat(item.created_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
                  </p>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="State">
                  <div class="flex md:justify-center">
                    <Badge :variant="resolveReportStatusBadge(item.state, item.failure_reason).variant">
                      {{ resolveReportStatusBadge(item.state, item.failure_reason).label }}
                    </Badge>
                  </div>
                </ResponsiveTableCell>
                <ResponsiveTableCell :cols="2" :cols-sm="1" label="Review Status">
                  <div class="flex md:justify-center">
                    <template v-if="item.review_status">
                      <Badge :variant="getReportReviewStatusBadge(item.review_status).variant">
                        {{ getReportReviewStatusBadge(item.review_status).label }}
                      </Badge>
                    </template>
                    <span v-else class="text-muted-foreground">N/A</span>
                  </div>
                </ResponsiveTableCell>
              </ResponsiveTableRow>
            </ResponsiveTableBody>
            <ResponsiveTableFooter v-if="totalCount > 0 && items.length > 0" :colspan="5" :cols="4" :cols-sm="4">
              <AppPagination :page="params.page" :size="params.size" :total="totalCount" label="reports" />
            </ResponsiveTableFooter>
          </ResponsiveTable>
        </template>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getReportList,
  type GetReportListResponse,
  type SortType,
  type ReportsSortBy,
  type ReportState,
  type ReportReviewStatus,
  type ReportType,
} from '~/client';
import { resolveReportStatusBadge } from '~/constants/reports/reportStatuses';
import { getReportReviewStatusBadge } from '~/constants/reports/reportReviewStatusConfig';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';
import { reportsGuidedEmpty } from '~/constants/guidedEmpty/reports';

definePageMeta({
  roles: ['admin'],
  backLabel: 'reports',
});

useHead({
  title: 'Reports',
});

const route = useRoute();
const { timezone } = useUserRole();

const params = computed(() => {
  const { subcontractor_company_ids, include_unassigned } = parseSubcontractorCompanyFilter(
    route.query.subcontractor_company_ids
  );
  const urlParams = {
    ...parsePagination(route.query),
    sort_by: (route.query.sort_by as ReportsSortBy) || 'created_at',
    sort_type: isSortType(route.query.sort_type as string) ? (route.query.sort_type as SortType) : 'desc',
    states: processArrayQueryParameterFromUrl<ReportState>(route.query.states),
    review_statuses: processArrayQueryParameterFromUrl<ReportReviewStatus>(route.query.review_statuses),
    types: processArrayQueryParameterFromUrl<ReportType>(route.query.types),
    canvasser_ids: processArrayQueryParameterFromUrl(route.query.canvasser_ids),
    project_ids: processArrayQueryParameterFromUrl(route.query.project_ids),
    subcontractor_company_ids,
    include_unassigned,
  };

  return Object.fromEntries(Object.entries(urlParams).filter(([_, value]) => value !== undefined)) as typeof urlParams;
});

const {
  data: reportData,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['reports-list', params.value],
  query: (): Promise<GetReportListResponse> =>
    getReportList({
      composable: '$fetch',
      query: params.value,
    }),
  staleTime: 0,
});

const items = computed(() => reportData.value?.items ?? []);
const totalCount = computed(() => reportData.value?.total_count ?? 0);

const isEmpty = computed(() => totalCount.value === 0 || items.value.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(reportsGuidedEmpty, isEmpty);
</script>
